(function() {
    'use strict';

    class RedGlobalAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Red Global — Supply Chain Architecture';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    briefingKey: 'r1_briefing',
                    panel: 'round1Panel'
                },
                {
                    titleKey: 'r2_title',
                    briefingKey: 'r2_briefing',
                    panel: 'round2Panel'
                },
                {
                    titleKey: 'r3_title',
                    briefingKey: 'r3_briefing',
                    panel: 'round3Panel'
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_briefing',
                    panel: 'round4Panel'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    ebitda: 8230,
                    usdExposure: 72,
                    avgLeadTime: 95,
                    safetyStockDays: 38,
                    budgetRemaining: 2800,
                    workingCapitalReleased: 0,
                    customerSatisfaction: 80,
                    aluminumBrazilPct: 0,
                    ppOption: '',
                    inkOption: '',
                    aluminumOption: '',
                    crisisImpact: 0,
                    disruptionDays: 0,
                    usdExposureHistory: [],
                    ebitdaHistory: [],
                    scoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    aluminumBrazilPct: 0,
                    safetyStockTarget: 38,
                    ppOption: 'A',
                    inkOption: 'D',
                    aluminumOption: 'G',
                    crisisResponse: 'emergency',
                    priceStrategy: 'immediate',
                    acquisition: 'no',
                    usdLever: 'financial'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var abInput = document.getElementById('aluminumBrazilInput');
                if (abInput) decisions.aluminumBrazilPct = parseInt(abInput.value);
                var ssInput = document.getElementById('safetyStockInput');
                if (ssInput) decisions.safetyStockTarget = parseInt(ssInput.value);

                if (isNaN(decisions.aluminumBrazilPct) || decisions.aluminumBrazilPct < 0 || decisions.aluminumBrazilPct > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_aluminum_pct'), 'warning'
                    );
                    return false;
                }
                if (isNaN(decisions.safetyStockTarget) || decisions.safetyStockTarget < 10 || decisions.safetyStockTarget > 60) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_safety_stock'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var ppSel = document.getElementById('ppOptionInput');
                if (ppSel) decisions.ppOption = ppSel.value;
                var inkSel = document.getElementById('inkOptionInput');
                if (inkSel) decisions.inkOption = inkSel.value;
                var aluSel = document.getElementById('aluminumOptionInput');
                if (aluSel) decisions.aluminumOption = aluSel.value;

                if (decisions.ppOption === 'C' && window.mySimulation.state.domainState.budgetRemaining < 4200) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_budget_c'), 'warning'
                    );
                }
            } else if (period === 3) {
                var crSel = document.getElementById('crisisResponseInput');
                if (crSel) decisions.crisisResponse = crSel.value;
                var psSel = document.getElementById('priceStrategyInput');
                if (psSel) decisions.priceStrategy = psSel.value;
            } else if (period === 4) {
                var acqSel = document.getElementById('acquisitionInput');
                if (acqSel) decisions.acquisition = acqSel.value;
                var levSel = document.getElementById('usdLeverInput');
                if (levSel) decisions.usdLever = levSel.value;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var ds = state.domainState;
            var d = state.decisions;
            var period = state.currentPeriod;
            var results = { period: period };

            if (period === 1) {
                ds.aluminumBrazilPct = d.aluminumBrazilPct;
                ds.safetyStockDays = d.safetyStockTarget;

                var oldSS = 38;
                var capitalFreed = Math.round((oldSS - ds.safetyStockDays) * 48.4);
                if (capitalFreed < 0) capitalFreed = 0;
                ds.workingCapitalReleased += capitalFreed;

                var aluLeadReduction = Math.round(d.aluminumBrazilPct * 0.95);
                ds.avgLeadTime = Math.round(95 - aluLeadReduction * 0.11 * 0.95);
                if (ds.avgLeadTime < 25) ds.avgLeadTime = 25;

                var chinaPrice = 4200;
                var brazilPrice = 5100;
                var blendedPrice = (chinaPrice * (100 - d.aluminumBrazilPct) + brazilPrice * d.aluminumBrazilPct) / 100;
                var annualCostDelta = Math.round((blendedPrice - chinaPrice) * 250 / 1000);
                var tcoSaving = Math.round(d.aluminumBrazilPct * 0.01 * (41.6 + 5.2 + 8.4));

                results.capitalFreed = capitalFreed;
                results.aluminumCostDelta = annualCostDelta;
                results.tcoSavings = Math.round(tcoSaving);
                results.newLeadTime = ds.avgLeadTime;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (d.aluminumBrazilPct >= 30 && d.aluminumBrazilPct <= 60) score += 25;
                else if (d.aluminumBrazilPct > 0) score += 10;
                if (ds.safetyStockDays >= 20 && ds.safetyStockDays <= 35) score += 25;
                else if (ds.safetyStockDays < 20) score += 5;
                else score += 15;

                results.roundScore = score;

            } else if (period === 2) {
                ds.ppOption = d.ppOption;
                ds.inkOption = d.inkOption;
                ds.aluminumOption = d.aluminumOption;

                var usdReduction = 0;
                var budgetUsed = 0;
                var ebitdaImpact = 0;
                var leadTimeChange = 0;

                if (d.ppOption === 'A') {
                    usdReduction += 0;
                    budgetUsed += 0;
                } else if (d.ppOption === 'B') {
                    usdReduction += 11.4;
                    budgetUsed += 200;
                    ebitdaImpact -= 1094;
                } else if (d.ppOption === 'C') {
                    usdReduction += 25;
                    budgetUsed += 4200;
                    ebitdaImpact -= 600;
                }

                if (d.inkOption === 'D') {
                    usdReduction += 7;
                    budgetUsed += 400;
                    leadTimeChange -= 60;
                } else if (d.inkOption === 'E') {
                    usdReduction += 0;
                    budgetUsed += 200;
                    ds.workingCapitalReleased += 320;
                }

                if (d.aluminumOption === 'F') {
                    budgetUsed += 600;
                    leadTimeChange -= 30;
                } else if (d.aluminumOption === 'G') {
                    budgetUsed += 350;
                    leadTimeChange -= 12;
                }

                var budgetExceeded = budgetUsed > ds.budgetRemaining;
                if (budgetExceeded) {
                    budgetUsed = ds.budgetRemaining;
                    if (d.ppOption === 'C') {
                        usdReduction -= 25;
                        usdReduction += 5;
                        ebitdaImpact += 600;
                        ebitdaImpact -= 200;
                    }
                }

                ds.budgetRemaining = Math.max(0, ds.budgetRemaining - budgetUsed);
                ds.usdExposure = Math.max(30, Math.round((ds.usdExposure - usdReduction) * 10) / 10);
                ds.ebitda = Math.max(1000, ds.ebitda + ebitdaImpact);
                ds.avgLeadTime = Math.max(25, ds.avgLeadTime + Math.round(leadTimeChange * 0.3));

                results.usdReduction = Math.round(usdReduction * 10) / 10;
                results.budgetUsed = budgetUsed;
                results.budgetExceeded = budgetExceeded;
                results.ebitdaImpact = ebitdaImpact;
                results.newUsdExposure = ds.usdExposure;
                results.newLeadTime = ds.avgLeadTime;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (ds.usdExposure <= 55) score += 30;
                else if (ds.usdExposure <= 62) score += 15;
                if (!budgetExceeded) score += 15;
                if (d.inkOption === 'D') score += 10;

                results.roundScore = score;

            } else if (period === 3) {
                var disruptionDays = 0;
                var alBrazil = ds.aluminumBrazilPct || 0;
                var aluOpt = ds.aluminumOption || 'G';

                if (aluOpt === 'F' || alBrazil >= 90) {
                    disruptionDays = 0;
                } else if (aluOpt === 'G' || alBrazil >= 40) {
                    var chinaShare = aluOpt === 'G' ? 60 : (100 - alBrazil);
                    disruptionDays = Math.round(chinaShare / 100 * 15);
                } else {
                    var ss = ds.safetyStockDays || 30;
                    disruptionDays = Math.max(0, 15 - Math.max(0, ss - 30));
                }
                ds.disruptionDays = disruptionDays;

                var productionLossPerDay = 16.1;
                var disruptionCost = 0;

                if (d.crisisResponse === 'emergency') {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.3 + disruptionDays * 8.5;
                    ds.customerSatisfaction -= 5;
                } else if (d.crisisResponse === 'ration') {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.6;
                    ds.customerSatisfaction -= 10;
                } else {
                    disruptionCost = disruptionDays * productionLossPerDay * 0.8;
                    ds.customerSatisfaction -= 15;
                }

                var devalImpact = ds.usdExposure * 0.22 * 480;
                var priceRecovery = 0;

                if (d.priceStrategy === 'immediate') {
                    priceRecovery = devalImpact * 0.85;
                    ds.customerSatisfaction -= 12;
                } else if (d.priceStrategy === 'gradual') {
                    priceRecovery = devalImpact * 0.55;
                    ds.customerSatisfaction -= 4;
                } else {
                    priceRecovery = devalImpact * 0.70;
                    ds.customerSatisfaction -= 2;
                }

                var netDevalCost = Math.round(devalImpact - priceRecovery);
                var totalCrisisCost = Math.round(disruptionCost + netDevalCost);
                ds.ebitda = Math.max(500, ds.ebitda - totalCrisisCost);
                ds.crisisImpact = totalCrisisCost;

                if (ds.customerSatisfaction < 20) ds.customerSatisfaction = 20;

                results.disruptionDays = disruptionDays;
                results.disruptionCost = Math.round(disruptionCost);
                results.devalImpact = Math.round(devalImpact);
                results.priceRecovery = Math.round(priceRecovery);
                results.netCrisisCost = totalCrisisCost;
                results.customerSatisfaction = ds.customerSatisfaction;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (disruptionDays <= 3) score += 20;
                else if (disruptionDays <= 8) score += 10;
                if (d.priceStrategy === 'differentiated') score += 15;
                else if (d.priceStrategy === 'gradual') score += 10;
                if (d.crisisResponse === 'emergency' && disruptionDays > 0) score += 10;
                else if (d.crisisResponse === 'ration') score += 8;
                if (ds.customerSatisfaction >= 60) score += 10;

                results.roundScore = score;

            } else if (period === 4) {
                var usdReduction4 = 0;
                var ebitdaChange = 0;

                if (d.acquisition === 'yes') {
                    ds.budgetRemaining -= 3200;
                    ebitdaChange += Math.round(12400 * 0.06);
                    if (ds.inkOption === 'D') {
                        usdReduction4 += 3;
                    } else {
                        usdReduction4 += 5;
                    }
                    ds.customerSatisfaction += 5;
                }

                if (d.usdLever === 'financial') {
                    usdReduction4 += 4;
                    ebitdaChange -= 180;
                } else if (d.usdLever === 'operational') {
                    usdReduction4 += 6;
                    ebitdaChange -= 350;
                } else {
                    usdReduction4 += 8;
                    ebitdaChange += 200;
                }

                ds.usdExposure = Math.max(30, Math.round((ds.usdExposure - usdReduction4) * 10) / 10);
                ds.ebitda += ebitdaChange;
                if (ds.ebitda < 500) ds.ebitda = 500;

                results.finalUsdExposure = ds.usdExposure;
                results.usdReduction = Math.round(usdReduction4 * 10) / 10;
                results.ebitdaChange = ebitdaChange;
                results.customerSatisfaction = ds.customerSatisfaction;
                results.targetAchieved = ds.usdExposure <= 50;
                results.usdExposure = ds.usdExposure;
                results.ebitda = ds.ebitda;

                var score = 0;
                if (ds.usdExposure <= 50) score += 25;
                else if (ds.usdExposure <= 55) score += 15;
                else score += 5;
                if (ds.customerSatisfaction >= 65) score += 10;
                if (d.acquisition === 'yes' && ds.inkOption !== 'D') score += 15;
                else if (d.acquisition === 'yes') score += 8;
                else score += 5;
                if (d.usdLever === 'commercial') score += 10;
                else if (d.usdLever === 'operational') score += 8;
                else score += 5;

                results.roundScore = score;
            }

            ds.usdExposureHistory.push(ds.usdExposure);
            ds.ebitdaHistory.push(ds.ebitda);
            ds.scoreHistory.push(results.roundScore || 0);

            // v1.1.0 FIX: persist a normalized 0-100 score into domainState so the
            // grading/reporting layer can read it. results_utils.php
            // (express_resolveDomainScore) reads domainState.performance.overallScore
            // (a normalized 0-100 grade) first, then top-level domainState.score.
            // The sim previously only tracked a per-round sum out of 110
            // (getPerformanceSummary.maxPossibleScore) and wrote no resolvable field,
            // so the instructor results panel showed an empty score.
            var _cum = ds.scoreHistory.reduce(function(s, v) { return s + (v || 0); }, 0);
            var _ov = Math.max(0, Math.min(100, Math.round(_cum / 110 * 100)));
            ds.performance = { overallScore: _ov, grade: (_ov >= 73 ? 'Expert' : _ov >= 55 ? 'Proficient' : _ov >= 36 ? 'Developing' : 'Beginner') };
            ds.score = _ov;
            results.overallScore = _ov;

            var self = this;
            setTimeout(function() {
                self._showRoundResults(state, results);
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return results;
        }

        _showRoundResults(state, results) {
            var panel = document.getElementById('roundResultsPanel');
            var text = document.getElementById('roundResultsText');
            if (!panel || !text) return;
            panel.style.display = 'block';

            var period = results.period;
            var html = '';

            if (period === 1) {
                html = '<strong>' + window.mySimulation.t('r1_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('capital_freed') + ': ARS ' + results.capitalFreed + 'M';
                html += '<br>' + window.mySimulation.t('aluminum_cost_delta') + ': USD ' + results.aluminumCostDelta + 'K/year';
                html += '<br>' + window.mySimulation.t('tco_savings') + ': USD ' + results.tcoSavings + 'K/year';
                html += '<br>' + window.mySimulation.t('new_lead_time') + ': ' + results.newLeadTime + ' days';
            } else if (period === 2) {
                html = '<strong>' + window.mySimulation.t('r2_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('usd_reduction') + ': ' + results.usdReduction + '%';
                html += '<br>' + window.mySimulation.t('new_usd_exposure') + ': ' + results.newUsdExposure + '%';
                html += '<br>' + window.mySimulation.t('budget_used') + ': ARS ' + results.budgetUsed + 'M';
                if (results.budgetExceeded) {
                    html += '<br><span style="color:#c0392b;font-weight:bold;">' + window.mySimulation.t('budget_exceeded_msg') + '</span>';
                }
            } else if (period === 3) {
                html = '<strong>' + window.mySimulation.t('r3_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('disruption_days') + ': ' + results.disruptionDays;
                html += '<br>' + window.mySimulation.t('disruption_cost') + ': ARS ' + results.disruptionCost + 'M';
                html += '<br>' + window.mySimulation.t('deval_impact') + ': ARS ' + results.devalImpact + 'M';
                html += '<br>' + window.mySimulation.t('price_recovery') + ': ARS ' + results.priceRecovery + 'M';
                html += '<br>' + window.mySimulation.t('net_crisis_cost') + ': ARS ' + results.netCrisisCost + 'M';
            } else if (period === 4) {
                html = '<strong>' + window.mySimulation.t('r4_result_title') + '</strong>';
                html += '<br>' + window.mySimulation.t('final_usd') + ': ' + results.finalUsdExposure + '%';
                if (results.targetAchieved) {
                    html += '<br><span style="color:#27ae60;font-weight:bold;">' + window.mySimulation.t('target_achieved') + '</span>';
                } else {
                    html += '<br><span style="color:#e67e22;font-weight:bold;">' + window.mySimulation.t('target_not_achieved') + '</span>';
                }
            }

            text.innerHTML = html;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitda',
                (v) => 'ARS ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('usdExposureDisplay', 'domainState.usdExposure',
                (v) => v + '%');
            uiManager.bind('leadTimeDisplay', 'domainState.avgLeadTime');
            uiManager.bind('safetyStockDisplay', 'domainState.safetyStockDays');
            uiManager.bind('budgetDisplay', 'domainState.budgetRemaining',
                (v) => 'ARS ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('wcReleasedDisplay', 'domainState.workingCapitalReleased',
                (v) => 'ARS ' + Math.round(v).toLocaleString() + 'M');
        }

        getChartConfig() {
            return {
                exposureChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'USD Exposure (%)',
                            data: [],
                            borderColor: '#c0392b',
                            backgroundColor: 'rgba(192,57,43,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'USD Exposure Over Rounds' } },
                        scales: { y: { min: 30, max: 80, beginAtZero: false } }
                    }
                },
                ebitdaChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'EBITDA (ARS M)',
                            data: [],
                            backgroundColor: 'rgba(44,82,130,0.7)',
                            borderColor: '#1a3a5c',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'EBITDA by Round' } },
                        scales: { y: { beginAtZero: false } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.usdExposureHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                exposureChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.usdExposureHistory }]
                },
                ebitdaChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.ebitdaHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var scores = history.map(function(r) { return r.results && r.results.roundScore ? r.results.roundScore : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var lastState = history[history.length - 1];
            var finalExposure = lastState.results ? lastState.results.usdExposure || 72 : 72;
            var finalEbitda = lastState.results ? lastState.results.ebitda || 8230 : 8230;
            var targetAchieved = finalExposure <= 50;

            var performance = 'Beginner Supply Chain Manager';
            if (totalScore >= 80 && targetAchieved) performance = 'Expert Supply Chain Strategist';
            else if (totalScore >= 60) performance = 'Proficient Supply Chain Manager';
            else if (totalScore >= 40) performance = 'Developing Supply Chain Manager';

            var insights = [];
            if (targetAchieved) {
                insights.push('Successfully reduced USD exposure to target level — strong strategic alignment.');
            } else {
                insights.push('USD exposure target was not fully achieved — consider more aggressive operational changes.');
            }
            if (finalEbitda >= 7000) {
                insights.push('EBITDA preserved well through the transformation — good cost management.');
            } else {
                insights.push('EBITDA erosion was significant — balance transformation costs with profitability.');
            }

            return {
                totalScore: totalScore,
                maxPossibleScore: 110,
                finalUsdExposure: finalExposure,
                finalEbitda: finalEbitda,
                targetAchieved: targetAchieved,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            if (period === 1 && results.roundScore < 20) {
                return window.mySimulation.t('hint_r1_low');
            }
            if (period === 2 && results.budgetExceeded) {
                return window.mySimulation.t('hint_budget');
            }
            if (period === 3 && results.disruptionDays > 10) {
                return window.mySimulation.t('hint_disruption');
            }
            if (period === 4 && state.domainState.usdExposure > 55) {
                return window.mySimulation.t('hint_exposure_high');
            }
            return null;
        }

